<?php
$page = 'admin';
$page_title = t('Initiative settings');
$user = current_user();
ensure_initiative_tables();

if (!is_admin()) {
    header('Location: index.php?page=work');
    exit;
}

$tabs = ['types', 'structure', 'workflow', 'financial', 'committee', 'permissions'];
$tab = in_array($_GET['tab'] ?? '', $tabs, true) ? (string) $_GET['tab'] : 'types';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    require_csrf_token();
    $action = (string) ($_POST['initiative_admin_action'] ?? '');
    try {
        switch ($action) {
            case 'type': initiative_admin_save_type($_POST); break;
            case 'delete_type': initiative_admin_delete_type((int) ($_POST['id'] ?? 0)); break;
            case 'category': initiative_admin_save_category($_POST); break;
            case 'delete_category': initiative_admin_delete_category((int) ($_POST['id'] ?? 0)); break;
            case 'org_unit': initiative_admin_save_org_unit($_POST); break;
            case 'delete_org_unit': initiative_admin_delete_org_unit((int) ($_POST['id'] ?? 0)); break;
            case 'reorder_org_units': initiative_admin_reorder_org_units(json_decode((string) ($_POST['order'] ?? '[]'), true) ?: []); break;
            case 'status': initiative_admin_save_status($_POST); break;
            case 'delete_status': initiative_admin_delete_status((int) ($_POST['id'] ?? 0)); break;
            case 'transition': initiative_workflow_save_transition($_POST); break;
            case 'delete_transition': initiative_workflow_delete_transition((int) ($_POST['id'] ?? 0)); break;
            case 'financial': initiative_admin_save_financial_settings($_POST, (int) $user['id']); break;
            case 'committee': initiative_admin_save_committee($_POST); break;
            case 'delete_committee': initiative_admin_delete_committee((int) ($_POST['id'] ?? 0)); break;
            case 'member': initiative_admin_add_committee_member((int) $_POST['committee_id'], (int) $_POST['user_id'], (string) ($_POST['member_role'] ?? ''), (float) ($_POST['weight'] ?? 1)); break;
            case 'delete_member': initiative_admin_delete_committee_member((int) $_POST['committee_id'], (int) $_POST['user_id']); break;
            case 'criterion': initiative_admin_save_criterion($_POST); break;
            case 'delete_criterion': initiative_admin_delete_criterion((int) ($_POST['id'] ?? 0)); break;
            case 'permissions': initiative_save_user_capabilities((int) $_POST['user_id'], (array) ($_POST['capabilities'] ?? [])); break;
            default: throw new InvalidArgumentException('Invalid action.');
        }
        flash(t('Initiative settings saved.'), 'success');
    } catch (Throwable $e) {
        flash(t($e->getMessage()), 'error');
    }
    header('Location: ' . url('admin', ['section' => 'initiatives', 'tab' => $tab]));
    exit;
}

$ref = initiative_reference_data();
$types = db_fetch_all('SELECT * FROM initiative_types ORDER BY sort_order, name');
$categories = db_fetch_all('SELECT * FROM initiative_categories ORDER BY sort_order, name');
$orgUnits = db_fetch_all('SELECT o.*, p.name parent_name, CONCAT(u.first_name," ",u.last_name) responsible_name FROM initiative_org_units o LEFT JOIN initiative_org_units p ON p.id=o.parent_id LEFT JOIN users u ON u.id=o.responsible_user_id ORDER BY o.sort_order,o.name');
$statuses = initiative_statuses(false);
$transitions = db_fetch_all('SELECT tr.*,a.name from_name,b.name to_name FROM initiative_status_transitions tr JOIN initiative_statuses a ON a.id=tr.from_status_id JOIN initiative_statuses b ON b.id=tr.to_status_id ORDER BY a.sort_order,b.sort_order');
$committees = db_fetch_all('SELECT * FROM initiative_committees ORDER BY is_active DESC,name');
$members = db_fetch_all('SELECT m.*,c.name committee_name,CONCAT(u.first_name," ",u.last_name) user_name FROM initiative_committee_members m JOIN initiative_committees c ON c.id=m.committee_id JOIN users u ON u.id=m.user_id ORDER BY c.name,u.first_name,u.last_name');
$criteria = db_fetch_all('SELECT c.*,co.name committee_name,t.name type_name FROM initiative_criteria c LEFT JOIN initiative_committees co ON co.id=c.committee_id LEFT JOIN initiative_types t ON t.id=c.initiative_type_id ORDER BY c.sort_order,c.name');
$agents = db_fetch_all("SELECT id,first_name,last_name,email,permissions FROM users WHERE role='agent' AND is_active=1 ORDER BY first_name,last_name");

$findById = static function (array $rows, int $id): ?array {
    foreach ($rows as $row) if ((int) $row['id'] === $id) return $row;
    return null;
};
$editingType = $findById($types, (int) ($_GET['edit_type'] ?? 0));
$editingCategory = $findById($categories, (int) ($_GET['edit_category'] ?? 0));
$editingOrg = $findById($orgUnits, (int) ($_GET['edit_org'] ?? 0));
$editingStatus = $findById($statuses, (int) ($_GET['edit_status'] ?? 0));
$editingTransition = $findById($transitions, (int) ($_GET['edit_transition'] ?? 0));
$editingCommittee = $findById($committees, (int) ($_GET['edit_committee'] ?? 0));
$editingCriterion = $findById($criteria, (int) ($_GET['edit_criterion'] ?? 0));

$initiativeTypeIcons = [
    'lightbulb'=>t('Idea'),'coins'=>t('Investment'),'bolt'=>t('Automation'),'cog'=>t('Process'),
    'shield'=>t('Compliance'),'chart-bar'=>t('Growth'),'building'=>t('Structure'),'tools'=>t('Implementation'),
    'star'=>t('Strategic'),'flag'=>t('Priority'),'globe'=>t('Expansion'),'check-circle'=>t('Quality'),
];
$requiredFieldOptions = [
    'summary'=>t('Summary'),'problem_statement'=>t('Current problem'),'opportunity'=>t('Opportunity'),
    'proposed_solution'=>t('Proposed solution'),'objective'=>t('Objective'),'impacted_process'=>t('Impacted process'),
    'impacted_audience'=>t('Impacted audience'),'systems_involved'=>t('Systems involved'),'risks'=>t('Risks'),
    'assumptions'=>t('Assumptions'),'dependencies'=>t('Dependencies'),'description'=>t('Full description'),
    'tags'=>t('Tags'),'target_date'=>t('Target date'),
];
$selectedRequiredFields = $editingType ? (json_decode((string) $editingType['required_fields_json'], true) ?: []) : [];
$selectedIcon = (string) ($editingType['icon'] ?? 'lightbulb');
$checkpointDays = json_decode(initiative_financial_setting('measurement_checkpoints', '[30,90,180,365]'), true) ?: [30,90,180,365];

$orgChildren = [];
foreach ($orgUnits as $row) $orgChildren[(int) ($row['parent_id'] ?? 0)][] = $row;
$flatOrgUnits = [];
$visitedOrg = [];
$walkOrg = function (int $parentId, int $depth) use (&$walkOrg, &$orgChildren, &$flatOrgUnits, &$visitedOrg): void {
    foreach ($orgChildren[$parentId] ?? [] as $row) {
        $id = (int) $row['id'];
        if (isset($visitedOrg[$id])) continue;
        $visitedOrg[$id] = true;
        $row['depth'] = $depth;
        $flatOrgUnits[] = $row;
        $walkOrg($id, $depth + 1);
    }
};
$walkOrg(0, 0);
foreach ($orgUnits as $row) if (!isset($visitedOrg[(int) $row['id']])) { $row['depth'] = 0; $flatOrgUnits[] = $row; }

$permissionUserId = (int) ($_GET['permission_user_id'] ?? ($agents[0]['id'] ?? 0));
$permissionUser = $findById($agents, $permissionUserId);
$permissionPayload = $permissionUser ? json_decode((string) ($permissionUser['permissions'] ?? ''), true) : [];
$configuredPermissions = is_array($permissionPayload) && is_array($permissionPayload['initiatives'] ?? null) ? $permissionPayload['initiatives'] : [];
$capabilityLabels = [
    'initiatives.view'=>[t('View initiatives'),t('Access initiatives related to the agent.')],
    'initiatives.view_all'=>[t('View all initiatives'),t('See initiatives from every owner and area.')],
    'initiatives.create'=>[t('Create initiatives'),t('Register new proposals.')],
    'initiatives.edit_own'=>[t('Edit own initiatives'),t('Edit proposals created by or assigned to the agent.')],
    'initiatives.edit_all'=>[t('Edit all initiatives'),t('Edit any proposal in the portfolio.')],
    'initiatives.delete'=>[t('Delete initiatives'),t('Permanently remove initiatives.')],
    'initiatives.submit'=>[t('Submit for review'),t('Move drafts into the review flow.')],
    'initiatives.triage'=>[t('Perform triage'),t('Classify, return, merge or reject proposals.')],
    'initiatives.approve'=>[t('Approve initiatives'),t('Request and record approval decisions.')],
    'initiatives.manage_execution'=>[t('Manage execution'),t('Link tickets, update execution and record measurements.')],
    'initiatives.finance_validate'=>[t('Validate financials'),t('Review validated costs and benefits.')],
    'initiatives.committee_evaluate'=>[t('Evaluate in committees'),t('Score initiatives using committee criteria.')],
    'initiatives.homologate'=>[t('Homologate initiatives'),t('Record the final governance decision.')],
    'initiatives.manage_settings'=>[t('Manage initiative settings'),t('Change types, structure and financial settings.')],
    'initiatives.manage_workflow'=>[t('Manage workflow'),t('Change statuses and allowed transitions.')],
    'initiatives.manage_committee'=>[t('Manage committees'),t('Change committees, members and criteria.')],
    'initiatives.view_financial'=>[t('View financial data'),t('See costs, benefits and return indicators.')],
    'initiatives.export'=>[t('Export portfolio'),t('Download initiative data as CSV.')],
    'initiatives.manage_portfolio'=>[t('Manage portfolio'),t('Manage rollout and strategic portfolio decisions.')],
];

require_once BASE_PATH . '/includes/header.php';
$baseTabUrl = static fn (string $targetTab, array $extra = []) => url('admin', array_merge(['section'=>'initiatives','tab'=>$targetTab], $extra));
?>
